s={(0,3),(0,4),(1,0),(1,2),(1,4),(2,1),(3,1)}
B={(0,0),(0,2),(0,4),(1,1),(2,1)}
def trans(points,rot,flip):
 out=set()
 for r,c in points:
  if flip:c=-c
  for _ in range(rot):r,c=c,-r
  out.add((r,c))
 mr=min(r for r,c in out);mc=min(c for r,c in out)
 return {(r-mr,c-mc) for r,c in out}
for f in [0,1]:
 for k in range(4):
  t=trans(s,k,f)
  print(k,f,t,'B subset?',B<=t,'intersection',len(B&t),'diff',t-B)
